extensionAttribute.scriptContentsMac:
#!/bin/zsh
# Updated by SecurityShrimp 2026 # Wireless Capability Extension Attribute # Targets macOS 12 through 26 (Tahoe), Intel and Apple Silicon # Original script's logic was inverted (reported No when Wi-Fi was present); # fixed to match the displayed semantics.
if /usr/sbin/networksetup -listallhardwareports 2>/dev/null \ | /usr/bin/grep -qE "Hardware Port: (Air|Wi-)"; then echo "<result>Yes</result>" else echo "<result>No</result>" fi
